-- H.K. Young importer (bourbon.hk_young), applied 2026-10-12
-- merge first: the seed 'H.K. Young Toasted Barrel Blend' (e85ed875) and 'H.K. Young Kentucky Straight Bourbon, Toasted Barrel Blend' (3d6b3440, the curated row: msrp, collection, mash) are one bottling; the curated row survives and the importer renames it.
select cellar.merge_product('e85ed875-f175-4ab1-9f31-d1d864f93b38'::uuid, '3d6b3440-bf4f-4e45-97f7-1adf5856e42b'::uuid, null);
-- Left alone: seed age 6 yr on the Toasted Barrel Blend; the maker states only '7 - 8 years' (a range) on /shop.
update cellar.products set proof = 117.4, spirit_type = 'bourbon', name = 'H.K. Young Toasted Barrel Blend', expression = 'Toasted Barrel Blend', aliases = (select array_agg(distinct a) from unnest(array_append(aliases, 'H.K. Young Kentucky Straight Bourbon, Toasted Barrel Blend')) a), producer = coalesce(producer, 'H.K. Young'), producer_id = coalesce(producer_id, '8d6a3db5-6012-4b63-98c4-cbe799db8b5c'::uuid), source = 'maker', source_url = 'https://hkyoungbourbon.com/ourblends', source_checked_at = now(), discontinued = false, is_core_range = true, catalog_included = true, rarity = coalesce(rarity, 'allocated'::cellar.rarity) where id = '3d6b3440-bf4f-4e45-97f7-1adf5856e42b' and facts_verified_at is null;
update cellar.products set source_checked_at = now() where id in ('3d6b3440-bf4f-4e45-97f7-1adf5856e42b');
update cellar.makers set website = coalesce(website, 'https://hkyoungbourbon.com'), country = coalesce(country, 'US'), updated_at = now() where id = '8d6a3db5-6012-4b63-98c4-cbe799db8b5c';
insert into cellar.products (type, status, source, specs, name, brand, brand_family, expression, producer, producer_id, proof, age_years, age_label, nas, expression_type, mash_style, mash_bill, spirit_type, bottled_in_bond, barrel_proof, finish, msrp_usd, is_core_range, catalog_included, aliases, image_url, source_url, source_checked_at, rarity)
select 'bourbon', 'confirmed', 'maker', case when r.img is null then '{}'::jsonb else jsonb_build_object('source_image_url', r.img) end, r.n, r.f, r.f, r.x, r.pr, r.mk::uuid, r.p, r.ay, r.al, r.nas, r.et::cellar.expression_type, r.ms::cellar.mash_style, r.mb, r.st::cellar.spirit_type, r.bib, r.bp, r.fin, r.msrp, r.core, true, coalesce(r.al2, '{}'::text[]), null, r.u, now(), r.rar::cellar.rarity
from jsonb_to_recordset($j$[{"n":"H.K. Young Toasted Small Batch","rar":"shelf","f":"H.K. Young","x":"Toasted Small Batch","p":91.4,"ay":null,"al":"6–7 yr","nas":false,"et":"small_batch","ms":"unknown","mb":null,"st":"bourbon","bib":false,"bp":false,"fin":"Toasted Barrel","msrp":null,"core":true,"al2":[],"img":"https://static.showit.co/1200/AW896c5Jeb_OGVkRsgHhqg/262434/0025_hky_c1600-min.jpg","u":"https://hkyoungbourbon.com/toasted-bourbon","pr":"H.K. Young","mk":"8d6a3db5-6012-4b63-98c4-cbe799db8b5c"},{"n":"H.K. Young Wheated Bourbon","rar":"allocated","f":"H.K. Young","x":"Wheated Bourbon","p":122.4,"ay":7.0,"al":"7 yr","nas":false,"et":"standard","ms":"wheated","mb":null,"st":"bourbon","bib":false,"bp":true,"fin":"Toasted Barrel","msrp":null,"core":true,"al2":["H.K. Young Toasted Wheat Blend","H.K. Young Wheated Barrel Blend"],"img":"https://static.showit.co/1200/WKHe8ELmca3fHljftZEwSA/262434/0020_hky_c1600-min.jpg","u":"https://hkyoungbourbon.com/wheated-blend","pr":"H.K. Young","mk":"8d6a3db5-6012-4b63-98c4-cbe799db8b5c"}]$j$::jsonb) as r(n text, f text, x text, p numeric, ay numeric, al text, nas bool, et text, ms text, mb text, st text, bib bool, bp bool, fin text, msrp numeric, core bool, al2 text[], img text, u text, pr text, mk text, rar text)
where not exists (select 1 from cellar.products e where e.type = 'bourbon' and e.merged_into is null and coalesce(e.brand_family, '') = coalesce(r.f, '') and coalesce(e.expression, '') = coalesce(r.x, '') and coalesce(e.release_label, '') = '');